  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_record_series_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_record_series_scope_node_id_code_version` (`tenant_id`, `scope_node_id`, `code`, `version`),
  CONSTRAINT `ck_record_series__classification` CHECK (`classification` IN ('public', 'internal', 'confidential', 'restricted', 'special')),
  CONSTRAINT `ck_record_series__status` CHECK (`status` IN ('draft', 'in_review', 'approved', 'published', 'superseded', 'retired', 'withdrawn'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[DOC/config/internal] File-plan record series with owner, classification and retention rule';

CREATE TABLE `redaction` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `document_id` BINARY(16) NOT NULL,
  `regions` JSON NOT NULL COMMENT 'Page regions redacted',
  `redacted_object_key` VARCHAR(1024) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `reviewed_by` BINARY(16),
  `released_at` DATETIME(6),
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  KEY `ix_redaction_document_id` (`tenant_id`, `document_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[DOC/transaction/confidential] Automatic redaction of third-party personal data before external release, with human review';

CREATE TABLE `scanned_page` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `batch_id` BINARY(16) NOT NULL,
  `document_id` BINARY(16),
  `sequence_no` INT UNSIGNED NOT NULL,
  `master_object_key` VARCHAR(1024) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `access_object_key` VARCHAR(1024) CHARACTER SET ascii COLLATE ascii_bin,
  `dpi` SMALLINT NOT NULL,
  `sha256` BINARY(32) NOT NULL,
  `ocr_confidence` DECIMAL(7,6),
  `document_type_guess` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin,
  `captured_at` DATETIME(6) NOT NULL,
  `qa_status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_scanned_page_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_scanned_page_batch_id_sequence_no` (`tenant_id`, `batch_id`, `sequence_no`),
  KEY `ix_scanned_page_document_id` (`tenant_id`, `document_id`),
  CONSTRAINT `ck_scanned_page__qa_status` CHECK (`qa_status` IN ('pending', 'auto_accepted', 'needs_review', 'verified', 'rejected'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[DOC/transaction/restricted] Page image captured from a batch (master TIFF/JPEG 2000 hashed at capture; access copy derived)';

-- ============================================================================
-- Domain INT — Intelligence and automation — alerts, investigations, improvement, recommendations, early warning, model register, agents, assistant and planning
-- ============================================================================

CREATE TABLE `document_extraction` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `document_id` BINARY(16) NOT NULL,
  `schema_code` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `fields` JSON NOT NULL COMMENT 'Field → value, confidence',
  `findings` JSON COMMENT 'Missing, duplicate, contradictory, expired documents; key dates with reminders',
  `validated_by` BINARY(16) COMMENT 'Consequential fields validated by a person',
  `validated_at` DATETIME(6),
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  KEY `ix_document_extraction_document_id` (`tenant_id`, `document_id`),
  CONSTRAINT `ck_document_extraction__status` CHECK (`status` IN ('pending', 'auto_accepted', 'needs_review', 'verified', 'rejected'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[INT/transaction/confidential] Document-intelligence extraction (forms, PDFs, certificates, transcripts, invoices) with per-field confidence and human validation';

-- ============================================================================
-- Domain AUD — Audit trail, chain anchors and the transactional outbox
-- ============================================================================

CREATE TABLE `audit_anchor` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `chain_id` BINARY(16) NOT NULL,
  `anchor_date` DATE NOT NULL,
  `last_chain_seq` BIGINT NOT NULL,
  `anchor_hash` BINARY(32) NOT NULL,
  `worm_object_key` VARCHAR(1024) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `verified_at` DATETIME(6),
  `verification_ok` BOOLEAN,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_audit_anchor_chain_id_anchor_date` (`tenant_id`, `chain_id`, `anchor_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[AUD/event/internal] Daily anchor of an audit chain written to write-once storage, and the nightly verification result';

CREATE TABLE `audit_event` (
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `chain_id` BINARY(16) NOT NULL COMMENT 'Tenant id (or the platform chain id in the platform zone)',
  `chain_seq` BIGINT NOT NULL COMMENT 'Monotonic sequence within the chain',
  `occurred_at` DATETIME(6) NOT NULL,
  `event_id` BINARY(16) NOT NULL COMMENT 'UUID v7 of the event',
  `actor_kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `actor_id` BINARY(16),
  `on_behalf_of_user_id` BINARY(16) COMMENT 'Agent X acting for Owner Y',
  `actor_grant_id` BINARY(16) COMMENT 'Active role-at-scope',
  `scope_node_id_at` BINARY(16) COMMENT 'Scope of the record at the time',
  `action` VARCHAR(80) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'e.g. learner.update, learner.nin.reveal, safeguarding_case.view, export.bulk',
  `record_kind` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `record_id` BINARY(16),
  `field_changes` JSON COMMENT '[{field, from, to}] — special-category values as hashes',
  `reason` VARCHAR(1000) COLLATE utf8mb4_0900_ai_ci,
  `purpose_code` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin COMMENT 'Required for restricted/special access',
  `approval_ref` BINARY(16),
  `correlation_id` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin,
  `ip` VARBINARY(16),
  `user_agent` VARCHAR(400) COLLATE utf8mb4_0900_ai_ci,
  `prev_hash` BINARY(32) NOT NULL,
  `hash` BINARY(32) NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  PRIMARY KEY (`chain_id`, `chain_seq`, `occurred_at`),
  KEY `ix_audit_event_record_kind_record_id` (`tenant_id`, `record_kind`, `record_id`),
  KEY `ix_audit_event_actor_id_occurred_at` (`tenant_id`, `actor_id`, `occurred_at`),
  CONSTRAINT `ck_audit_event__actor_kind` CHECK (`actor_kind` IN ('user', 'agent', 'api_client', 'system', 'platform_operator'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[AUD/event/restricted] Tamper-evident audit event (append-only, hash-chained per tenant and zone, partitioned by day)'
