ALTER TABLE `custody_event` ADD CONSTRAINT `fk_custody_event__batch_id` FOREIGN KEY (`tenant_id`, `batch_id`) REFERENCES `digitisation_batch` (`tenant_id`, `id`);
ALTER TABLE `digitisation_batch` ADD CONSTRAINT `fk_digitisation_batch__survey_id` FOREIGN KEY (`tenant_id`, `survey_id`) REFERENCES `digitisation_site_survey` (`tenant_id`, `id`);
ALTER TABLE `digitisation_batch` ADD CONSTRAINT `fk_digitisation_batch__record_series_id` FOREIGN KEY (`tenant_id`, `record_series_id`) REFERENCES `record_series` (`tenant_id`, `id`);
ALTER TABLE `disposal` ADD CONSTRAINT `fk_disposal__record_series_id` FOREIGN KEY (`tenant_id`, `record_series_id`) REFERENCES `record_series` (`tenant_id`, `id`);
ALTER TABLE `document` ADD CONSTRAINT `fk_document__category_id` FOREIGN KEY (`tenant_id`, `category_id`) REFERENCES `document_category` (`tenant_id`, `id`);
ALTER TABLE `document` ADD CONSTRAINT `fk_document__batch_id` FOREIGN KEY (`tenant_id`, `batch_id`) REFERENCES `digitisation_batch` (`tenant_id`, `id`);
ALTER TABLE `document_category` ADD CONSTRAINT `fk_document_category__record_series_id` FOREIGN KEY (`tenant_id`, `record_series_id`) REFERENCES `record_series` (`tenant_id`, `id`);
ALTER TABLE `document_link` ADD CONSTRAINT `fk_document_link__document_id` FOREIGN KEY (`tenant_id`, `document_id`) REFERENCES `document` (`tenant_id`, `id`);
ALTER TABLE `extracted_field` ADD CONSTRAINT `fk_extracted_field__page_id` FOREIGN KEY (`tenant_id`, `page_id`) REFERENCES `scanned_page` (`tenant_id`, `id`);
ALTER TABLE `qa_sample` ADD CONSTRAINT `fk_qa_sample__batch_id` FOREIGN KEY (`tenant_id`, `batch_id`) REFERENCES `digitisation_batch` (`tenant_id`, `id`);
ALTER TABLE `redaction` ADD CONSTRAINT `fk_redaction__document_id` FOREIGN KEY (`tenant_id`, `document_id`) REFERENCES `document` (`tenant_id`, `id`);
ALTER TABLE `scanned_page` ADD CONSTRAINT `fk_scanned_page__batch_id` FOREIGN KEY (`tenant_id`, `batch_id`) REFERENCES `digitisation_batch` (`tenant_id`, `id`);
ALTER TABLE `scanned_page` ADD CONSTRAINT `fk_scanned_page__document_id` FOREIGN KEY (`tenant_id`, `document_id`) REFERENCES `document` (`tenant_id`, `id`);
