-- ============================================================================
-- Append-only guards (second line of defence; the application account also lacks UPDATE/DELETE)
-- ============================================================================
CREATE TRIGGER `tr_custody_event__no_update` BEFORE UPDATE ON `custody_event` FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'custody_event is append-only (UPDATE refused)';
CREATE TRIGGER `tr_custody_event__no_delete` BEFORE DELETE ON `custody_event` FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'custody_event is append-only (DELETE refused)';
CREATE TRIGGER `tr_qa_sample__no_update` BEFORE UPDATE ON `qa_sample` FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'qa_sample is append-only (UPDATE refused)';
CREATE TRIGGER `tr_qa_sample__no_delete` BEFORE DELETE ON `qa_sample` FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'qa_sample is append-only (DELETE refused)';
CREATE TRIGGER `tr_audit_anchor__no_update` BEFORE UPDATE ON `audit_anchor` FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'audit_anchor is append-only (UPDATE refused)';
CREATE TRIGGER `tr_audit_anchor__no_delete` BEFORE DELETE ON `audit_anchor` FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'audit_anchor is append-only (DELETE refused)';
CREATE TRIGGER `tr_audit_event__no_update` BEFORE UPDATE ON `audit_event` FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'audit_event is append-only (UPDATE refused)';
CREATE TRIGGER `tr_audit_event__no_delete` BEFORE DELETE ON `audit_event` FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'audit_event is append-only (DELETE refused)';
